            if gt in conf_targets: hits_confusion += 1

    pool.append({'input': s.get('input_preview',''), 'target': gt, 'tok': q_tok})
    if not ok:
        p = _normalize(pred)
        if p and p != gt:
            confusion[p][gt] += 1.0; confusion[gt][p] += 0.5
    _decay(confusion)

